import Image from 'next/image';

interface ImageWithSEOProps {
  src: string
  alt: string
  width: number
  height: number
}

export default function ImageWithSEO({ src, alt, width, height }: ImageWithSEOProps) {
  return (
    <Image
      src={src}
      alt={alt}
      width={width}
      height={height}
      loading="lazy"
      quality={90}
      placeholder="blur"
      blurDataURL="data:image/jpeg;base64,"
    />
  )
} 